<script setup lang="ts">
import AppIcon from '../AppIcon.vue'
import type { DocumentFilters } from '../../stores/documents'
defineProps<{ modelValue: DocumentFilters; view: 'list' | 'card'; tags: { id: number; name: string }[] }>()
const emit = defineEmits<{ 'update:modelValue': [value: DocumentFilters]; 'update:view': [value: 'list' | 'card']; upload: [files: File[]]; folders: [] }>()
const patch = (model: DocumentFilters, update: Partial<DocumentFilters>) => emit('update:modelValue', { ...model, ...update })
const choose = (event: Event) => { const files = Array.from((event.target as HTMLInputElement).files ?? []); if (files.length) emit('upload', files); (event.target as HTMLInputElement).value = '' }
</script>
<template><div class="document-toolbar"><button class="button secondary folders-trigger" @click="$emit('folders')">文件夹</button><label class="toolbar-search"><span class="sr-only">搜索资料</span><AppIcon name="search"/><input :value="modelValue.query ?? ''" type="search" placeholder="搜索资料名称" @input="patch(modelValue, { query: ($event.target as HTMLInputElement).value || undefined })" /></label><select aria-label="资料类型" :value="modelValue.type ?? ''" @change="patch(modelValue, { type: ($event.target as HTMLSelectElement).value || undefined })"><option value="">全部类型</option><option value="PDF">PDF</option><option value="MARKDOWN">Markdown</option><option value="TEXT">文本</option><option value="CODE">代码</option></select><select aria-label="资料标签" :value="modelValue.tagId ?? ''" @change="patch(modelValue, { tagId: Number(($event.target as HTMLSelectElement).value) || undefined })"><option value="">全部标签</option><option v-for="tag in tags" :key="tag.id" :value="tag.id">{{ tag.name }}</option></select><label class="check-filter"><input type="checkbox" :checked="modelValue.favorite" @change="patch(modelValue, { favorite: ($event.target as HTMLInputElement).checked || undefined })"/>仅收藏</label><select aria-label="资料排序" :value="modelValue.sort" @change="patch(modelValue, { sort: ($event.target as HTMLSelectElement).value as DocumentFilters['sort'] })"><option value="updated-desc">最近更新</option><option value="updated-asc">最早更新</option><option value="name-asc">名称 A–Z</option><option value="name-desc">名称 Z–A</option></select><div class="view-toggle"><button :class="{ active: view === 'list' }" aria-label="列表视图" @click="$emit('update:view','list')"><AppIcon name="list"/></button><button :class="{ active: view === 'card' }" aria-label="卡片视图" @click="$emit('update:view','card')"><AppIcon name="grid"/></button></div><label class="button primary upload-button"><AppIcon name="upload"/>上传资料<input type="file" multiple accept=".pdf,.md,.markdown,.txt,.java,.xml,.yml,.yaml,.sql,.js,.ts,.json,.properties,.sh,.ps1" @change="choose"/></label></div></template>
